async function install(){
 if(window.CLMDailyQueueReady)await window.CLMDailyQueueReady;
 db.recovery=db.recovery||{};
 if(db.recovery[version])return;
 db.drafts=db.drafts||[];
 const queue=db.dailyActionQueue;
 if(!queue)return;
 for(const item of packages){
  const draft=structuredClone(item.draft),q=structuredClone(item.queue);
  const old=db.drafts.find(d=>d.id===draft.id);
  if(old&&(old.sentAt||old.gmailMessageId))continue;
  if(old)Object.assign(old,draft);else db.drafts.push(draft);
  const prior=queue.entries.find(e=>e.id===q.id);
  if(prior)Object.assign(prior,q,{receipts:prior.receipts||q.receipts||[]});else queue.entries.push(q);
 }
 const merged=new Set(['bg-20261015-dries-men','bg-20261015-ralph-men']);
 queue.entries=queue.entries.filter(q=>!merged.has(q.id)||(q.receipts||[]).length);
 if(packages.some(p=>p.draft.id===db.activeDraftId))db.draft=structuredClone(db.drafts.find(d=>d.id===db.activeDraftId));
 db.recovery[version]=true;
 if(!await persistWorkspaceSafe(true)){delete db.recovery[version];throw Error('Could not save reviewed brand packages');}
 renderTables();window.CLMDailyQueue?.render();
}
const run=()=>install().catch(error=>console.error('Reviewed package loading failed',error));
if(window.__clmWorkspaceReady)run();else window.addEventListener('clm:workspace-ready',run,{once:true});
